-- ============================================================================
-- 2026-10-09
-- Course 6 (Simple FAQ Chatbot): replace the Python/Streamlit guide with the
--   no-code "Get Claude to build your FAQ chatbot, then publish it for free"
--   guide (Claude writes one index.html, Netlify hosts it, optional Gemini).
-- Course 11 (Calendar & Task Prioritizer): add session.video, the walkthrough
--   recording at /videos/calendar-task-prioritizer-walkthrough.mp4.
--
-- Source of truth: supabase/course-content-drafts/6-simple-faq-chatbot.sql and
-- 11-calendar-task-prioritizer-agent.sql (same content; minified here so it fits
-- through the Supabase MCP).
--
-- Guards: every new value is checked against the md5 of the reviewed text, and
-- both live rows must still be the versions this was written against. End state
-- is checked against the expected jsonb text. One transaction. Backup of both
-- rows (RLS on, anon/authenticated revoked):
--   course_content_backup_20261009_faq_video
--
-- Needs the SessionGuide/PromptBox update (session.video, promptKind 'example')
-- and public/videos/calendar-task-prioritizer-walkthrough.mp4 deployed first.
--
-- Rollback:
--   update public.course_content c set
--     what_you_build = b.what_you_build, what_you_learn = b.what_you_learn,
--     session = b.session, troubleshooting = b.troubleshooting,
--     resources = b.resources, updated_at = now()
--   from public.course_content_backup_20261009_faq_video b
--   where c.course_id = b.course_id and b.course_id in (6, 11);
-- ============================================================================

do $mig$
declare
  v_wyb   text := $wyb$A friendly FAQ chatbot for your business, built without writing code. You plan your questions and answers, Claude turns them into one self-contained web page (index.html), and you publish it free on Netlify so anyone can open it from a link or see it on your website. It only answers from your FAQ and never invents an answer: when it is not sure, it says so, shows your contact details and offers the closest questions. An optional upgrade adds free Gemini AI for unusual wording, still answering only from your FAQ.$wyb$;
  v_wyl   text := $wyl$["Plan an FAQ a bot can match: short, factual answers plus the extra words people actually use","Write one clear build prompt and get Claude to produce a complete, working web page","Save and open an HTML file correctly on Windows or Mac","Test the bot like a real customer and have Claude fix what it misses","Publish a site free with Netlify Drop and update it in seconds","Add the chatbot to WordPress, Wix or Squarespace, or share it as a link or QR code","Optionally keep an API key private with a Cloudflare Worker that calls Gemini"]$wyl$;
  v_sess  text := $sess${"model":"Claude chat (free account), optional Gemini","totalTime":"75 min","buildCount":8,"whatYouNeed":["A laptop or desktop computer (phones make saving and uploading files hard)","A free Claude account at claude.ai","Your business name, contact details and the questions customers ask you most","A free Netlify account to put the bot online (Build 6)","Optional, for Build 8 only: a free Gemini API key and a free Cloudflare account"],"outcomes":["Plan an FAQ that a bot can match, with short answers and the extra words people use","Get Claude to build a complete chatbot as one index.html file, with no coding","Test it like a real customer and have Claude fix what it misses","Publish it free on Netlify and open it from your phone","Put it on your website or share the link anywhere","Optionally add Gemini for unusual wording, still answering only from your FAQ"],"builds":[{"number":1,"title":"Get ready","time":"10 min","description":"You will not write code. You copy a prompt, paste it to Claude, save what Claude gives you, and put it online.","steps":[{"instruction":"Know what you are building. An FAQ chatbot is a small chat window on a web page. A visitor types \"do you deliver?\" and the bot replies with the answer you wrote. It only knows what you give it, so it cannot invent answers. If it does not know, it says so and shows your contact details.","callout":{"variant":"tip","text":"The whole bot is **one file** named **index.html**. A web page is just a text file that browsers can display. **Claude writes that file for you** from a prompt, and you then publish it free with Netlify."}},{"instruction":"Learn the words you will see in this guide.","table":{"header":["Word","Meaning"],"rows":[["Prompt","The message you send Claude. In this guide you copy prompts from the boxes."],["Browser","Chrome, Safari, Edge or Firefox."],["Text editor","A program for plain text, like Notepad."],["Host / deploy","Put your file on the internet so anyone can open it by link."],["Embed","Show your chatbot inside another website."]]}},{"instruction":"Check you have a laptop or desktop computer, and that you can chat with Claude at claude.ai. A free account is fine.","verify":"You can open claude.ai on your computer and start a new chat."},{"instruction":"On your Desktop, create a folder named my-faq-bot. Everything for this build goes in it."},{"instruction":"Turn on file extensions. The extension is the end of a file name, like .html. Hidden extensions cause confusing mistakes later.","table":{"header":["Computer","How to show extensions"],"rows":[["Windows 11","Open the folder, click **View**, then **Show**, then tick **File name extensions**."],["Windows 10","Open the folder, click **View**, tick **File name extensions**."],["Mac","In Finder go to **Finder**, **Settings**, **Advanced**, tick **Show all filename extensions**."]]},"verify":"Files in your folder now show their endings, such as .txt or .html."}]},{"number":2,"title":"Plan your FAQ on paper","time":"15 min","description":"The bot is only as good as the content you give it, so do this first.","steps":[{"instruction":"Collect questions. Check your WhatsApp chats, emails and DMs for what customers ask. Aim for 15 to 30. Starting something new? Imagine a first-time visitor."},{"instruction":"Write each answer in 1 to 3 short sentences with real facts: prices, times, addresses, deadlines."},{"instruction":"Add extra words for each one. These are other words people might use. For \"Do you deliver?\" the extras are delivery shipping dispatch send bring fee. This is what makes the bot feel smart.","callout":{"variant":"tip","text":"No extras yet? Skip them. In Build 3 you can tell Claude to **invent the extra words for you**."}},{"instruction":"Write everything in a Notepad file in this layout, starting with your business name and contact details:","prompt":"Business name: Golden Crust Bakery\nContact: Call 0803-000-0000 or email hello@example.com\n\nQ: Do you deliver?\nA: Yes, within the city for a flat 1,500 fee.\nExtras: delivery shipping dispatch send bring fee\n\nQ: What are your opening hours?\nA: Tuesday to Sunday, 8 AM to 7 PM. Closed Mondays.\nExtras: open close time schedule hours monday","promptKind":"example","callout":{"variant":"warning","text":"Do not include private customer information or passwords. Anyone can read what is in the file."},"verify":"You have a Notepad file with your business name, contact details, and at least 10 questions and answers."}]},{"number":3,"title":"Ask Claude to build the chatbot","time":"10 min","description":"One prompt turns your FAQ into a complete chatbot. It matches questions in plain JavaScript, so it needs no API key and works offline.","steps":[{"instruction":"Open a new chat with Claude."},{"instruction":"Click Copy on the prompt below and paste it into the message box.","prompt":"Build me a complete FAQ chatbot as ONE self-contained HTML file (no external libraries, no API keys, works offline, free). I am a complete beginner, so keep it simple and put everything I need to edit in one clearly labelled section at the top of the script.\n\nRequirements:\n1. At the top of the script, a section labelled \"EDIT THIS SECTION ONLY\" with: BUSINESS_NAME, CONTACT (shown when the bot cannot answer), a FAQS list where each entry has q (question), a (answer) and k (extra words people might use, including synonyms and slang), PROXY_URL (empty string for now, for an optional AI upgrade later) and CONFIDENCE (a number 0 to 1, default 0.34).\n2. Matching with plain JavaScript: lowercase the visitor's text, remove common filler words, simple stemming (strip s, es, ed, ing), then score each FAQ by overlap with its question, its extra words, and its answer. Show the best answer only if its score is above CONFIDENCE.\n3. If no answer is confident enough: say \"I'm not sure about that one\", show CONTACT, and offer up to 3 of the closest questions as tappable buttons. The bot must NEVER guess or invent answers.\n4. A friendly welcome message and 4 tappable quick-question buttons.\n5. Save every unanswered question to the browser's localStorage, with a small \"Copy list of unanswered questions\" button at the bottom.\n6. If PROXY_URL is not empty and the local match is not confident, POST {question, faqs:[{q,a}]} to PROXY_URL as JSON and show the \"answer\" field from the reply if there is one. If that fails, fall back to the normal \"not sure\" message.\n7. Clean, modern, mobile-friendly design with a chat window, message bubbles, light and dark mode, and large readable text. Use textContent (not innerHTML) for visitor text.\n8. Comment the code in plain English so a beginner can follow it.\n\nPut my content into the FAQS list. Where an entry has no extra words, invent good ones. Fix any small spelling issues in my questions.\n\nGive me the result as a downloadable file named index.html if you can. If you cannot, give it as one code block.\n\nMY FAQ:\n[PASTE YOUR FAQ HERE]"},{"instruction":"Replace the line [PASTE YOUR FAQ HERE] with everything from your Notepad file (Build 2)."},{"instruction":"Press Enter. Claude builds the chatbot in under a minute.","verify":"Claude has replied with the chatbot, as a file or a code block."}]},{"number":4,"title":"Save the file and try it","time":"10 min","description":"Claude gives you the chatbot either as a download or as a code block. Either way it ends up as index.html in your my-faq-bot folder.","steps":[{"instruction":"If Claude gave you a download, click it, then move index.html into your my-faq-bot folder."},{"instruction":"If Claude gave you a code block, click the Copy button on the code block, then save it carefully:","table":{"header":["Computer","How to save it"],"rows":[["Windows","Open **Notepad** and press **Ctrl + V**. Then **File**, **Save As**. Set **Save as type** to **All files**, **File name** to **index.html**, **Encoding** to **UTF-8**, and save inside **my-faq-bot**."],["Mac","Open **TextEdit**, choose **Format**, then **Make Plain Text**, and paste with **Cmd + V**. Then **File**, **Save**. Name it **index.html** and click **Use .html** if asked."]]}},{"instruction":"Double-click index.html. It opens in your browser with your chatbot."},{"instruction":"Ask a question from your list, then ask something unrelated like \"What is the capital of France?\". The bot should say it is not sure and show your contact details.","callout":{"variant":"warning","text":"See code text instead of a chat window? The file was saved as **index.html.txt** or as rich text. Turn on extensions (Build 1) and save it again as above."},"verify":"Your chatbot opens from index.html and shows your business name."}]},{"number":5,"title":"Test it and let Claude fix it","time":"10 min","description":"Real visitors word things differently from your list. Find the misses now and let Claude fix them.","steps":[{"instruction":"Ask 10 questions the way a real person would, not copied from your list. A friend can help."},{"instruction":"Write down every question the bot got wrong or missed."},{"instruction":"Go back to the same Claude chat, paste this prompt and fill in your list:","prompt":"Please update the chatbot. These questions were answered wrongly or not answered:\n- [question 1] (should give the answer about: [topic])\n- [question 2] (should give the answer about: [topic])\n\nAdd the words from these questions to the matching entries' extra words (k), or add new FAQ entries if needed. Give me the full updated index.html file."},{"instruction":"Save the new file over your old index.html, refresh the browser, and test again."},{"instruction":"Click Copy list of unanswered questions at the bottom of the bot. Paste the list into Claude with this message:","prompt":"Here are questions my bot could not answer. Draft short answers for the ones that fit an FAQ, and tell me which ones I must answer myself.","callout":{"variant":"tip","title":"Too strict or too loose?","text":"Tell Claude \"Make the bot stricter\" or \"Make the bot more forgiving\". It will change the CONFIDENCE number."},"verify":"Your bot answers at least 8 of 10 test questions correctly."}]},{"number":6,"title":"Put it on the internet for free","time":"10 min","description":"Netlify hosts simple sites like this one for free.","steps":[{"instruction":"Make sure your my-faq-bot folder contains a file named exactly index.html (not index.html.txt)."},{"instruction":"Go to app.netlify.com/drop in your browser. Sign up if asked (Google or email). This stops your site from expiring."},{"instruction":"Drag the whole my-faq-bot folder onto the page."},{"instruction":"After a few seconds you get a link like https://random-name.netlify.app. Open it on your phone. Your chatbot is live.","verify":"Your chatbot opens from that link on your phone."},{"instruction":"Optional: in Netlify, open Site configuration and change the site name to something nicer, like mybusiness-faq."},{"instruction":"To update it later, ask Claude for changes (the Build 5 prompt), save the new index.html, then drag the folder onto your site's Deploys page in Netlify. It takes about 30 seconds.","callout":{"variant":"tip","text":"Other free hosts that work the same way: GitHub Pages and Cloudflare Pages."}}]},{"number":7,"title":"Use it on your website or anywhere","time":"10 min","description":"Three ways to put the bot in front of customers. Use your own Netlify link wherever you see your-site.netlify.app.","steps":[{"instruction":"Option A: show it inside your website. Copy this code and replace the address with your own Netlify link:","prompt":"<iframe src=\"https://your-site.netlify.app\"\n  style=\"width:100%;max-width:420px;height:600px;border:0;border-radius:12px\"\n  title=\"FAQ chatbot\"></iframe>","promptKind":"code"},{"instruction":"Paste the code in the right place for your website builder:","table":{"header":["Website builder","Where to paste"],"rows":[["WordPress","Edit a page, add a **Custom HTML** block, paste."],["Wix","Add, then Embed Code, then **Embed a Site**, enter your link."],["Squarespace","Add a **Code** block, paste."],["Hand-written HTML","Paste inside the **<body>**."]]},"callout":{"variant":"warning","text":"If nothing shows, your plan may block embeds. Use Option B."}},{"instruction":"Option B: share the link. Put it in your WhatsApp status and business profile, Instagram bio, email signature, Facebook buttons or invoices. For print, make a QR code of the link with any free QR generator."},{"instruction":"Option C: use your own web address. If you own a domain, open Domain management in Netlify and add something like faq.yourbusiness.com. Netlify shows the exact steps."}],"goFurther":"Keep it fresh every week: copy the unanswered list and ask Claude to add the useful ones, update prices and hours the day they change, then re-upload to Netlify."},{"number":8,"title":"Optional upgrade: add AI","time":"20 min","description":"Skip this until Builds 1 to 7 work. AI helps with unusual wording. It still answers only from your FAQ, and if it is unavailable the bot falls back to its normal behaviour.","steps":[{"instruction":"Get Claude to write the helper. The helper (a Cloudflare Worker) keeps your key private. Paste this prompt into a Claude chat and save the result as worker.js.","prompt":"Write a Cloudflare Worker (a single worker.js file, ES module format) for my FAQ chatbot. It must:\n- Accept POST requests with JSON {question, faqs:[{q,a}]} and answer CORS preflight (OPTIONS).\n- Call the Google Gemini API (model \"gemini-flash-latest\", generateContent endpoint) with my key from the Worker secret env.GEMINI_API_KEY, sent in the x-goog-api-key header, never in the URL.\n- Use a system instruction that says: answer ONLY from the FAQ provided, never guess, keep it short, and reply with exactly NO_MATCH if the FAQ does not cover it.\n- Return JSON {answer: \"...\"} on success, and {} if the model says NO_MATCH, if there is any error, or if the free limit is hit.\n- Limit the question to 500 characters and the FAQ text to 12000 characters.\n- Include comments in plain English, and a comment showing where to replace the allowed website address (CORS).\nExplain in 5 short steps how to deploy it on Cloudflare Workers for free and add the secret."},{"instruction":"Get a free key. Go to aistudio.google.com/apikey, sign in with Google, click Create API key, and copy it.","callout":{"variant":"warning","text":"Never paste the key into your web page or share it. It goes only into the Worker's secret settings."}},{"instruction":"Create a free Cloudflare account at dash.cloudflare.com, then go to Workers & Pages, Create, Hello World, Deploy."},{"instruction":"Click Edit code, delete everything, paste the contents of worker.js, and click Deploy."},{"instruction":"In the Worker's Settings, open Variables and Secrets and add a Secret named exactly GEMINI_API_KEY with your key."},{"instruction":"Copy the Worker's address (it looks like https://something.workers.dev)."},{"instruction":"Connect it. Send Claude this message with your Worker's address, save the new file, upload it to Netlify, and test with an oddly worded question.","prompt":"Set PROXY_URL in my chatbot to https://something.workers.dev and give me the full updated index.html","callout":{"variant":"warning","title":"Free-tier limits.","text":"Google's free tier has request limits that change over time, and content sent to it may be used to improve Google products. Keep private data out of your FAQ and check Google's rate-limits page if the AI stops answering."}},{"instruction":"Lock it down: ask Claude to show you where in worker.js to replace \"*\" with your site address, so other sites cannot use your Worker.","verify":"An oddly worded question gets a correct answer from your FAQ, and an unrelated one still gets the \"not sure\" message."}]}],"portfolio":"You built and published a working FAQ chatbot for a real business without writing code, and it answers only from your own FAQ. Share the live link, plus a screenshot of it answering a real question and correctly saying it is not sure about an unrelated one.","portfolioPrompt":"I just built an FAQ chatbot for [business name] without writing code. I planned the questions and answers, had Claude build it as a single HTML file that matches visitors' questions to my FAQ, never guesses, shows my contact details when it is not sure, and logs unanswered questions. I published it free on Netlify and [embedded it on my website / shared the link]. [Optional: I added Gemini through a Cloudflare Worker to handle unusual wording.]\n\nHelp me write:\n1. A 2-3 sentence project description for my portfolio site\n2. A short LinkedIn post announcing it\n3. Three resume-style bullet points describing what I built and the skills it shows"}$sess$;
  v_tsh   text := $tsh$[{"issue":"I see code instead of a chat window","fix":"The file was saved as .txt or as rich text. Save it again with the Build 4 settings."},{"issue":"The page is blank","fix":"Tell Claude: \"My chatbot page is blank. Here is the file,\" and paste it. Ask for a fixed version."},{"issue":"Netlify says \"Page not found\"","fix":"The file must be named exactly index.html and sit directly in the folder you dropped."},{"issue":"Changes don't show","fix":"Save, then refresh. Press Ctrl + F5 to force it."},{"issue":"Wrong answers or too many \"not sure\" replies","fix":"Use the Build 5 prompt, or tell Claude to make the bot stricter or more forgiving."},{"issue":"The AI doesn't answer","fix":"The Worker secret must be named exactly GEMINI_API_KEY. The bot still works without it."},{"issue":"The embed shows nothing","fix":"Your website plan may block embeds. Share the direct link instead."},{"issue":"Stuck on a step","fix":"Tell Claude the build and step number and what you see on your screen, and ask it to walk you through the fix."}]$tsh$;
  v_res   text := $res$[{"title":"Claude (free account)","url":"https://claude.ai"},{"title":"Netlify Drop: publish a folder by dragging it","url":"https://app.netlify.com/drop"},{"title":"Netlify documentation","url":"https://docs.netlify.com"},{"title":"Google AI Studio: create a Gemini API key","url":"https://aistudio.google.com/apikey"},{"title":"Cloudflare Workers documentation","url":"https://developers.cloudflare.com/workers/"}]$res$;
  v_video text := $video${"url":"/videos/calendar-task-prioritizer-walkthrough.mp4","title":"Watch the full build","duration":"16 min","text":"Follow along as every step is done on screen, from creating the key to the first plan email.","note":"The email in the video uses an earlier purple design. The code in this guide sends the blue version."}$video$;
  n int;
begin
  if to_regclass('public.course_content_backup_20261009_faq_video') is not null then
    raise exception 'course_content_backup_20261009_faq_video already exists - has this already run?';
  end if;

  if md5(v_wyb)   <> 'd81f2134c16d1ed0d293385d0e21f915'  then raise exception 'what_you_build text changed in transit'; end if;
  if md5(v_wyl)   <> 'b16aa9fd23915bc1264d55f77687db56'  then raise exception 'what_you_learn text changed in transit'; end if;
  if md5(v_sess)  <> '431ead61d87a57e13989d51dd1e75cb9' then raise exception 'session text changed in transit'; end if;
  if md5(v_tsh)   <> '0859b89c1fb56370029eea269ed09584'  then raise exception 'troubleshooting text changed in transit'; end if;
  if md5(v_res)   <> '8fb74b0192d485f64a372180b40c543c'  then raise exception 'resources text changed in transit'; end if;
  if md5(v_video) <> 'd37361dbcb25e894b8e3c466f45cf1f7' then raise exception 'video text changed in transit'; end if;

  if (select md5(coalesce(what_you_build, '') || what_you_learn::text || session::text || troubleshooting::text || resources::text)
        from public.course_content where course_id = 6) is distinct from '79a297c586a0730741d6a12dc45c8064' then
    raise exception 'live row 6 is not the 2026-09-26 published version - nothing was changed';
  end if;
  if (select md5(session::text) from public.course_content where course_id = 11) is distinct from '606b53c731e379ece6de121c678600d1' then
    raise exception 'live row 11 session is not the 2026-10-08 version - nothing was changed';
  end if;

  create table public.course_content_backup_20261009_faq_video as
    select * from public.course_content where course_id in (6, 11);
  alter table public.course_content_backup_20261009_faq_video enable row level security;
  revoke all on public.course_content_backup_20261009_faq_video from anon, authenticated;

  update public.course_content set
    what_you_build  = v_wyb,
    what_you_learn  = v_wyl::jsonb,
    session         = v_sess::jsonb,
    troubleshooting = v_tsh::jsonb,
    resources       = v_res::jsonb,
    updated_at      = now()
  where course_id = 6;
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'expected to update exactly 1 row for course 6, updated %', n; end if;

  update public.course_content set
    session    = jsonb_set(session, '{video}', v_video::jsonb, true),
    updated_at = now()
  where course_id = 11;
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'expected to update exactly 1 row for course 11, updated %', n; end if;

  -- end-state assertions: the stored jsonb is exactly the reviewed content
  if (select md5(what_you_build) from public.course_content where course_id = 6) <> 'd81f2134c16d1ed0d293385d0e21f915' then
    raise exception 'course 6 what_you_build is not the reviewed text';
  end if;
  if (select md5(what_you_learn::text) from public.course_content where course_id = 6) <> 'a8da1b2c1a2ed47070ccf922cdccfbfc' then
    raise exception 'course 6 what_you_learn is not the reviewed content';
  end if;
  if (select md5(session::text) from public.course_content where course_id = 6) <> '4f361cfd0452044a929926165c85452f' then
    raise exception 'course 6 session is not the reviewed content';
  end if;
  if (select md5(troubleshooting::text) from public.course_content where course_id = 6) <> '11654e446afee8e327f02028f2087c0e' then
    raise exception 'course 6 troubleshooting is not the reviewed content';
  end if;
  if (select md5(resources::text) from public.course_content where course_id = 6) <> 'f40eba4f357ab299ef3cd96c66ea39e6' then
    raise exception 'course 6 resources is not the reviewed content';
  end if;
  if (select md5(session::text) from public.course_content where course_id = 11) <> '24f9d64e9b9148924560afb44fdc4326' then
    raise exception 'course 11 session is not the reviewed content plus the video link';
  end if;
end
$mig$;
